import {CAMPAIGNS,campaignInfo,campaignProgress,chapterFor,campaignMap} from './campaign-content.js';
import {DEITIES,BY_ID,FAVOUR,ENEMIES,MAPS,enemyKey} from './data.js';
import {Battle} from './engine.js';
import {CHAPTERS,DIFFICULTIES} from './journey-content.js';
import {SAVE_KEY,PROGRESS_KEY,emptyJourney,migrateJourney,recordVictory,introductions,challengeProgress} from './campaign.js';
import {CAST,briefingFor,targetAvailability,encounterStyle,fieldLine,victoryLine} from './experience.js';
import {createRenderer,paintEnemyPortrait} from './renderer.js';
const $=id=>document.getElementById(id),canvas=$('board'),images={};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let stored=read(PROGRESS_KEY,null),journey=stored?.version===2?stored:migrateJourney(read('temple-guardians-progress-v1',{}));
if(!journey.temples||!Array.isArray(journey.seen)||!Array.isArray(journey.stories)||!Array.isArray(journey.festival))journey=emptyJourney();
journey.metMira??=journey.stories.length>0;
const rootJourney=journey;let menuCampaign='river';
let saved=read(SAVE_KEY,null),battle;
try{battle=new Battle(saved?.version===5&&MAPS[saved.mapIndex]?saved.mapIndex:0,saved?.version===5?saved:null,{encounter:0});}catch{battle=new Battle(0,null,{encounter:0});}
journey=campaignProgress(rootJourney,battle.campaignId);
let menuOpen=true,hasBattle=!!saved?.version;
let paused=battle.status==='fighting',speed=1,selectedPlot=null,selectedDeity='agni',sound=false,audio=null,endHandled=false,wonAge=0,ready=false,last=0,uiClock=0,saveClock=0,confirmAction=null,pendingWave=null,introCards=[],introIndex=0;
let targeting=null,inspectedEnemy=null,lastFieldKey='',fieldUntil=0;
function beginTarget(kind,plot){const available=targetAvailability(battle,plot,kind);if(!available.ok){battle.message=available.label;updateUI();return false;}targeting={kind,plot};paused=false;updateUI();$('targetControls').scrollIntoView({block:'nearest'});return true;}
function cancelTarget(){targeting=null;paused=false;updateUI();save();}
function continueJourney(){newBattle(battle.encounter<2?battle.mapIndex:battle.mapIndex+1,battle.encounter<2?battle.encounter+1:0);}

const draw=createRenderer(canvas,images),activeDialogs=()=>!!document.querySelector('dialog[open]');
function save(){try{if(hasBattle)localStorage.setItem(SAVE_KEY,JSON.stringify({...battle.snapshot(),version:5}));localStorage.setItem(PROGRESS_KEY,JSON.stringify(rootJourney));}catch{$('message').textContent='Browser storage is unavailable; progress cannot be saved after closing.';}}
function tone(kind){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();let notes=kind==='bell'?[784,1176,1568]:kind==='strike'?[196,392]:kind==='upgrade'?[523,784,1046]:kind==='wave'?[196,294]:kind==='won'?[523,659,784,1046]:kind==='leak'?[150]:[440,660];notes.forEach((f,i)=>{let o=audio.createOscillator(),g=audio.createGain();o.type=kind==='wave'?'triangle':'sine';o.frequency.value=f;let t=audio.currentTime+i*.11;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.075,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+.7);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.75);});}catch{sound=false;$('sound').textContent='Sound unavailable';}}
function spriteStyle(d,level=1){return `background-image:url('assets/${level===3?'exalted':level===2?'honoured':'shrines'}.webp');background-position:${(d.atlas%4)/3*100}% ${d.atlas<4?0:100}%;`;}
function sprite(d,level=1,klass='selection-art'){return `<div class="${klass} sprite-shrine tier-${level}" style="${spriteStyle(d,level)}" aria-hidden="true"></div>`;}
function refreshPlots(){$('plotSelect').innerHTML='<option value="">Tap a numbered plot</option>'+battle.map.plots.map((_,i)=>{let s=battle.shrines.find(s=>s.plot===i);return `<option value="${i}">Plot ${i+1}${s?' — '+BY_ID[s.deity].name:''}</option>`;}).join('');$('plotSelect').value=selectedPlot===null?'':String(selectedPlot);}
function initRoster(){$('deities').innerHTML=DEITIES.map(d=>`<button class="deity" data-deity="${d.id}" style="--accent:${d.colour}" aria-label="${d.name}: ${d.role}, ${d.cost} offerings">${sprite(d,1,'thumb')}<span class="deity-name">${d.name}</span><span class="role">${d.role}</span><span class="price">${d.cost} <span>offerings</span></span><i class="accent-line"></i></button>`).join('');for(let button of document.querySelectorAll('[data-deity]'))button.onclick=()=>{if(!ready)return;selectedDeity=button.dataset.deity;let s=battle.shrines.find(s=>s.plot===selectedPlot);if(selectedPlot!==null&&!s){if(!battle.build(selectedPlot,selectedDeity))battle.message='More offerings are needed for this shrine.';refreshPlots();}else if(s){selectedPlot=null;refreshPlots();battle.message='Choose an empty plot for your next shrine.';}else battle.message=`Choose a plot to establish ${BY_ID[selectedDeity].name}.`;updateSelection();updateUI();save();};}
function updateSelection(){let s=battle.shrines.find(s=>s.plot===selectedPlot),d=BY_ID[s?.deity||selectedDeity];
 if(selectedPlot===null)$('selection').innerHTML=`${sprite(d)}<h2>${d.name}</h2><div class="selection-domain" style="color:${d.colour}">${d.domain} · ${d.role}</div><p>${d.description}</p><p class="selection-hint">Choose a numbered plot to establish a shrine. Each shrine has a distinct role. Saraswati supports; Durga awaits your target.</p>`;
 else if(!s)$('selection').innerHTML=`<h2>Plot ${selectedPlot+1}</h2><p>Choose a shrine below, or establish ${d.name} here.</p>${sprite(d)}<div class="selection-actions"><button id="build" class="primary">Establish ${d.name} · ${d.cost}</button></div>`;
 else $('selection').innerHTML=`${sprite(d,s.level)}<h2>${d.name}</h2><div class="selection-domain" style="color:${d.colour}">${FAVOUR[s.level-1]} · Plot ${s.plot+1}</div><div class="favour-level">${[1,2,3].map(i=>`<i class="${i<=s.level?'on':''}"></i>`).join('')}</div><p>${d.description}</p>${s.level<3?`<div class="upgrade-preview"><span>NEXT: ${FAVOUR[s.level].toUpperCase()}</span><p>${d.changes[s.level-1]}</p></div>`:'<p class="upgrade-preview">Exalted favour. This shrine has reached its full strength.</p>'}<div class="selection-actions">${s.level<3?`<button id="upgrade" class="primary">Raise favour · ${d.upgrade[s.level-1]}</button>`:'<button disabled>Exalted shrine</button>'}<button id="intervene">Call intervention</button><button id="sell" class="sell">Rebuild elsewhere · return ${Math.floor(s.spent*.85)}</button></div><p class="intervention-help">${d.intervention}</p>`;
 if($('build'))$('build').onclick=()=>{if(battle.build(selectedPlot,selectedDeity)){refreshPlots();updateSelection();updateUI();save();}};
 if($('upgrade'))$('upgrade').onclick=()=>{battle.upgrade(selectedPlot);updateSelection();updateUI();save();};
 if($('sell'))$('sell').onclick=()=>{battle.sell(selectedPlot);refreshPlots();updateSelection();updateUI();save();};
 if($('intervene'))$('intervene').onclick=()=>{const shrine=battle.shrines.find(s=>s.plot===selectedPlot);if(['vayu','prithvi'].includes(shrine.deity)){beginTarget('intervention',selectedPlot);battle.message='Time is paused. Choose a point, check the marked area, then confirm.';}else {battle.intervention(selectedPlot);if(shrine.deity==='durga')beginTarget('strike',selectedPlot);}updateUI();save();};
 if(s?.deity==='durga'){const button=document.createElement('button');button.id='strikeButton';button.className='primary';button.textContent='Choose a foe for Durga';$('selection').append(button);button.onclick=()=>beginTarget('strike',s.plot);}
 if(s&&!['durga','saraswati','agni'].includes(s.deity)){const label=document.createElement('label');label.className='target-priority';label.textContent='Target priority';const select=document.createElement('select');for(const [value,name] of [['first','First to the temple'],['strongest','Strongest'],['groups','Largest group']])select.add(new Option(name,value));select.value=s.targeting;select.onchange=()=>{s.targeting=select.value;save();};label.append(select);$('selection').append(label);}

 for(let button of document.querySelectorAll('[data-deity]')){let active=button.dataset.deity===d.id;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active));}
}
function preview(){let next=battle.wave<battle.totalWaves?battle.waves[battle.wave]:null,current=battle.waves[Math.max(0,battle.wave-1)],entries=next||current||[];$('previewTitle').textContent=battle.status==='won'?(battle.mode==='quick'?'Battle won':battle.encounter===2?'Temple restored':'Encounter won'):next?`Next wave · ${battle.wave+1}`:`Final wave · ${battle.totalWaves}`;
 if(battle.status==='won'){$('previewEnemies').innerHTML='<span class="enemy-chip">The army has been turned back.</span>';$('boonText').textContent='';return;}
 const groups={};for(let e of entries){let key=(e.name||e.type)+'|'+(e.protection||'');groups[key]??={...e,count:0};groups[key].count++;}
 $('previewEnemies').innerHTML=Object.values(groups).map(e=>`<span class="enemy-chip">${e.count} × ${e.type==='boss'?battle.map.bossName:e.name||ENEMIES[e.type].name}${e.protection?`<small>${BY_ID[e.protection].name}’s protection</small>`:e.type==='shade'?'<small>Hidden · Saraswati reveals</small>':''}</span>`).join('');
 $('boonText').textContent=entries.some(e=>e.type==='boss')?battle.map.boon:entries.some(e=>e.type==='winged')?'Vayu’s powerful wind deals extra damage to flying foes.':'';
}
function updateUI(){
 $('offerings').textContent=battle.offerings;$('shield').textContent=`${battle.shield} / ${battle.map.shield}`;$('wave').textContent=`${battle.wave} / ${battle.mode==='survival'?'∞':battle.totalWaves}`;$('mapName').textContent=battle.map.name;document.querySelector('.map-tag').textContent=battle.map.points.at(-1)[0]<600?'← Protect the temple':'Protect the temple →';$('chapterLabel').textContent=battle.mode==='survival'?'THE UNENDING VIGIL':`${battle.mode==='quick'?'QUICK BATTLE':campaignInfo(battle.campaignId).name.toUpperCase()+' · '+(battle.encounter+1)+'/3'} · ${DIFFICULTIES[battle.difficulty].name}`;$('meterValue').textContent=Math.floor(battle.meter)+'%';$('meterFill').style.width=battle.meter+'%';$('meterFill').parentElement.classList.toggle('ready',battle.meter>=100);
 $('pause').textContent=targeting?'Cancel and resume':paused?'Resume':'Pause';$('pause').setAttribute('aria-pressed',String(paused));$('pause').disabled=battle.status!=='fighting';
 $('waveButton').disabled=!ready||battle.status!=='planning';$('waveButton').textContent=battle.status==='planning'?`Begin wave ${battle.wave+1} →`:battle.status==='fighting'?`Wave ${battle.wave} in progress`:battle.status==='won'?(battle.encounter===2?'Temple restored':'Encounter won'):'Battle ended';
 $('earlyButton').hidden=battle.status!=='fighting'||battle.wave>=battle.totalWaves;$('earlyButton').disabled=!battle.canCallEarly();$('earlyButton').textContent=battle.canCallEarly()?`Call wave ${battle.wave+1} early · +${battle.earlyReward()}`:'Early call available after foes arrive';
 $('message').textContent=paused&&battle.status==='fighting'?'Paused. Build, upgrade or plan your next intervention.':battle.message;
 $('progressText').textContent=battle.mode==='quick'?'Standalone defence · campaign progress is unchanged':`${campaignInfo(battle.campaignId).name} · ${Object.keys(journey.temples).length} / 5 temples restored · saved on this browser`;
 $('challengeName').textContent=battle.mode==='quick'?'Hold the sanctuary through every wave. Campaign lamps are not awarded.':battle.encounter===2?battle.map.challenge:'Reach the commander to earn this temple’s three lamps.';$('challengeProgress').textContent=battle.mode==='quick'?`${battle.totalWaves} waves · replay keeps the same enemy mix`:battle.encounter===2?challengeProgress(battle):`Encounter ${battle.encounter+1} of 3 · optional escort bonus available`;
 $('activeWaves').textContent=battle.activeWaves.length>1?`Waves ${battle.activeWaves.join(' + ')} overlap`:battle.status==='fighting'?`${battle.enemies.length} foes on the path`:battle.status==='won'?(battle.mode==='quick'?'Quick battle complete':'The journey continues'):`One battle · ${battle.totalWaves} waves`;
 let s=battle.shrines.find(s=>s.plot===selectedPlot);if($('upgrade'))$('upgrade').disabled=battle.offerings<BY_ID[s.deity].upgrade[s.level-1]||['won','lost'].includes(battle.status);if($('intervene'))$('intervene').disabled=battle.meter<100||battle.status!=='fighting'||(s?.deity==='durga'&&s.empowered);if($('build'))$('build').disabled=!ready||battle.offerings<BY_ID[selectedDeity].cost||['won','lost'].includes(battle.status);preview();
 for(let e of battle.events.splice(0))tone(e.type);
 updateFieldDialogue();
 $('postBattle').hidden=!['won','lost'].includes(battle.status);$('continueBattle').hidden=battle.status!=='won'||battle.mode!=='campaign'||(battle.mapIndex===4&&battle.encounter===2);
 updateActiveControls();
 if(!menuOpen&&battle.survivalBlessingDue&&!activeDialogs())openDialog('survivalDialog');
 if(!menuOpen&&['won','lost'].includes(battle.status)&&!endHandled){endHandled=true;wonAge=0;showResult();}
}
function lampsHTML(lamps,labels=true){return `<div class="achievement-lamps">${['Victory','Shield intact','Challenge'].map((name,i)=>`<span class="achievement ${lamps[i]?'lit':''}" aria-label="${name}: ${lamps[i]?'earned':'not yet earned'}"><span aria-hidden="true">🪔</span>${labels?`<small>${name}</small>`:''}</span>`).join('')}</div>`;}
function showResult(){const won=battle.status==='won',reward=won?recordVictory(journey,battle):null,partial=reward?.encounterOnly||battle.mode==='quick';
 if(battle.mode==='survival')journey.survivalBest=Math.max(journey.survivalBest||0,battle.completedWaves.length);
 if(reward?.festivalUnlocked&&!journey.festival.includes(battle.map.id))journey.festival.push(battle.map.id);save();
 $('result').hidden=false;$('result').innerHTML=`<span class="panel-eyebrow">${won?'THE LIGHT RETURNS':'THE DEFENCE HAS FALLEN'}</span><h2>${won?(battle.mode==='quick'?'Sanctuary defended':partial?'The way is open':battle.map.name+' restored'):battle.mode==='survival'?`Vigil ended · ${battle.completedWaves.length} waves`:'The shield has fallen'}</h2><p>${won?victoryLine(battle):'The murtis still stand. Try another balance of damage, control and revelation.'}</p>${won&&reward&&!partial?lampsHTML(reward.lamps):''}${reward?.festivalUnlocked?'<p class="festival-reward">All three lamps lit. Festival decorations unlocked.</p>':''}<div class="result-buttons">${won&&battle.mode==='campaign'&&(battle.mapIndex<4||battle.encounter<2)?'<button class="primary" id="nextTemple">Continue the journey →</button>':''}<button id="retry">${won?(partial?'Replay encounter':'Replay for the lamps'):'Try again'}</button><button id="lookAround">${won&&!partial?'See the restored temple':'See the battlefield'}</button></div>${won&&!partial?`<p class="story-next">${battle.map.next}</p>`:''}`;
 $('retry').onclick=()=>newBattle(battle.mapIndex,battle.encounter,battle.mode);if($('nextTemple'))$('nextTemple').onclick=()=>newBattle(battle.encounter<2?battle.mapIndex:battle.mapIndex+1,battle.encounter<2?battle.encounter+1:0);$('lookAround').onclick=()=>{$('result').hidden=true;$('postBattle').scrollIntoView({block:'nearest'});};
}
function choosePlot(i){selectedPlot=i;let s=battle.shrines.find(s=>s.plot===i);if(s)selectedDeity=s.deity;refreshPlots();updateSelection();updateUI();}
canvas.addEventListener('pointerdown',e=>{if(!ready)return;let rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*1200,y=(e.clientY-rect.top)/rect.height*650,nearest=-1,best=Infinity;const enemy=battle.enemies.filter(e=>e.hp>0).map(e=>({e,p:battle.pos(e)})).filter(({p})=>Math.abs(p.x-x)<40&&y>p.y-110&&y<p.y+20).sort((a,b)=>Math.abs(a.p.x-x)-Math.abs(b.p.x-x))[0]?.e;if(targeting){if(targeting.kind==='strike'){if(enemy&&battle.strike(targeting.plot,enemy.id)){targeting=null;updateUI();save();}else battle.message='Choose a visible foe without Durga’s protection.';}else {let point=nearestPathPoint(x,y);if(point.distance<100){targeting.point=point;battle.message='Check the marked area, then confirm your intervention.';updateUI();}else battle.message='Choose a point on the path.';}return;}if(enemy){inspectedEnemy=enemy.id;updateUI();return;}inspectedEnemy=null;battle.map.plots.forEach(([px,py],i)=>{let distance=Math.hypot(px-x,py-y);if(battle.shrines.some(s=>s.plot===i)&&Math.abs(px-x)<50&&y>py-150&&y<py+18)distance=Math.min(distance,18);if(distance<best){best=distance;nearest=i;}});if(best<62)choosePlot(nearest);});
$('plotSelect').onchange=e=>{if(e.target.value===''){selectedPlot=null;updateSelection();}else choosePlot(Number(e.target.value));};
function openDialog(id){$(id).showModal();}function closeDialog(id){$(id).close();}
function openStory(){const m=battle.map,briefing=briefingFor(battle,journey),person=CAST[briefing.speaker];$('keeperName').textContent=person.name+' · '+person.role;$('keeperWords').textContent=briefing.text;$('storyArt').src=`assets/${m.art}.webp`;$('storyChapter').textContent=m.subtitle;$('storyTitle').textContent=battle.mode==='survival'?'The unending vigil':chapterFor(battle).encounters[battle.encounter];$('storyIntro').textContent=battle.mode==='survival'?'The river flows again, but scattered asura hosts still approach the First Spring. Keep its lamps burning through the unending vigil.':chapterFor(battle).scenes[battle.encounter];$('storyGoal').textContent=battle.mode==='survival'?'Survive escalating waves; choose help every five waves.':`Survive ${battle.totalWaves} waves${battle.encounter===2?' and overcome the commander':''}. Optional: ${chapterFor(battle).objective.toLowerCase()}.`;$('difficultySelect').value=battle.difficulty;$('blessingSelect').value=battle.blessing;for(const id of ['difficultySelect','blessingSelect'])$(id).disabled=battle.wave>0||battle.shrines.length>0;$('storyGoal').textContent=encounterStyle(battle)+'. '+$('storyGoal').textContent;$('storyChallenge').textContent=m.challenge;openDialog('storyDialog');}
$('storyContinue').onclick=()=>{journey.metMira=true;if(!journey.stories.includes(battle.map.id))journey.stories.push(battle.map.id);closeDialog('storyDialog');save();};$('chapterStory').onclick=openStory;
function requestWave(early=false){if(!ready||pendingWave||activeDialogs())return;if(early?!battle.canCallEarly():battle.status!=='planning')return;pendingWave={early};introCards=introductions(battle.waves[battle.wave],battle.mapIndex,journey.seen,battle.map);introIndex=0;if(introCards.length){renderIntroduction();openDialog('enemyDialog');}else finishWaveRequest();}
function renderIntroduction(){const card=introCards[introIndex];$('enemyName').textContent=card.name;$('enemyQuote').textContent='“'+card.quote+'”';$('enemyHint').textContent=card.hint;$('enemyProtection').textContent=card.protectionText;$('enemyProtection').hidden=!card.protectionText;$('enemyCounter').textContent=`NEW FOE · ${introIndex+1} / ${introCards.length}`;$('enemyContinue').textContent=introIndex+1<introCards.length?'Meet the next foe →':pendingWave?.early?'Call the wave early':'Begin the wave →';paintEnemyPortrait($('enemyPortrait'),images[card.atlas]||images.enemies,card.family,card.cell??null);}
function finishWaveRequest(){let request=pendingWave;pendingWave=null;if(!request)return;for(let card of introCards)if(!journey.seen.includes(card.key))journey.seen.push(card.key);if($('enemyDialog').open)closeDialog('enemyDialog');battle.startWave(request.early);paused=false;updateUI();save();}
$('enemyContinue').onclick=()=>{if(++introIndex<introCards.length)renderIntroduction();else finishWaveRequest();};$('enemyCancel').onclick=()=>{pendingWave=null;closeDialog('enemyDialog');};$('enemyDialog').addEventListener('cancel',()=>{pendingWave=null;});
$('waveButton').onclick=()=>requestWave(false);$('earlyButton').onclick=()=>requestWave(true);$('pause').onclick=()=>{if(targeting){cancelTarget();return;}paused=!paused;updateUI();save();};$('speed').onclick=()=>{speed={1:2,2:5,5:1}[speed];$('speed').textContent=speed+'×';$('speed').setAttribute('aria-label',`Battle speed ${speed} times. Click to change.`);};
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));if(sound)tone('upgrade');};$('guide').onclick=()=>openDialog('guideDialog');
for(let b of document.querySelectorAll('[data-close]'))b.onclick=()=>closeDialog(b.dataset.close);
function openCampaign(id=battle.campaignId){menuCampaign=typeof id==='string'?id:battle.campaignId;const progressJourney=campaignProgress(rootJourney,menuCampaign);const count=Object.keys(progressJourney.temples).length;$('journeySummary').textContent=`${campaignInfo(menuCampaign).name} · ${count} of 5 temples restored. ${campaignInfo(menuCampaign).rule}`;
 $('mapChoices').innerHTML=MAPS.map((_,i)=>{const m=campaignMap(i,menuCampaign);let progress=progressJourney.temples[m.id],lamps=progress?.lamps||[false,false,false],festival=lamps.every(Boolean);return `<article class="journey-stop ${progress?'restored':''}"><span class="journey-number">${i+1}</span><button class="map-choice" data-map="${i}"><img src="assets/${m.art}.webp" alt="${m.name}"><div><small>${m.subtitle}</small><strong>${m.name}</strong><span>${progress?'Restored · best shield '+progress.shield+'/20':m.note}</span>${lampsHTML(lamps,false)}</div></button><div class="encounter-choices">${chapterFor({mapIndex:i,campaignId:menuCampaign,mode:'campaign'}).encounters.map((name,k)=>`<button data-encounter="${i}:${k}">${progressJourney.encounters?.[m.id+':'+k]||k===2&&progress?'✓ ':''}${k+1}. ${name}${progressJourney.difficulties?.[battle.difficulty]?.[m.id+':'+k]?.[0]?' · '+DIFFICULTIES[battle.difficulty].name+' won':''}</button>`).join('')}</div>${festival?`<button class="festival-toggle" data-festival="${m.id}" aria-pressed="${progressJourney.festival.includes(m.id)}">Festival decoration: ${progressJourney.festival.includes(m.id)?'on':'off'}</button>`:''}</article>`;}).join('');
 for(let b of document.querySelectorAll('[data-map]'))b.onclick=()=>{closeDialog('campaignDialog');const i=Number(b.dataset.map);if((battle.wave>0||battle.shrines.length>0)&&!['won','lost'].includes(battle.status))askConfirm('Leave this battle?','This battle will restart. Restored temples and earned lamps remain saved.','Change temple',()=>newBattle(i,0,'campaign',menuCampaign));else newBattle(i,0,'campaign',menuCampaign);};
 for(let b of document.querySelectorAll('[data-festival]'))b.onclick=()=>{const id=b.dataset.festival;if(progressJourney.festival.includes(id))progressJourney.festival=progressJourney.festival.filter(x=>x!==id);else progressJourney.festival.push(id);b.textContent='Festival decoration: '+(progressJourney.festival.includes(id)?'on':'off');b.setAttribute('aria-pressed',String(progressJourney.festival.includes(id)));save();};for(const b of document.querySelectorAll('[data-encounter]'))b.onclick=()=>{const [i,k]=b.dataset.encounter.split(':').map(Number);closeDialog('campaignDialog');if((battle.wave||battle.shrines.length)&&!['won','lost'].includes(battle.status))askConfirm('Leave this battle?','Saved victories remain; the current defence restarts.','Change encounter',()=>newBattle(i,k,'campaign',menuCampaign));else newBattle(i,k,'campaign',menuCampaign);};$('survivalButton').disabled=Object.keys(rootJourney.temples).length<5;$('campaignTitle').textContent=campaignInfo(menuCampaign).name;openDialog('campaignDialog');
}
$('campaign').onclick=()=>openCampaign();
function openJournal(){const cards=[],keys=new Set();if(battle.mode==='quick')for(const card of introductions(battle.waves.flat(),battle.mapIndex,[],battle.map)){if(journey.seen.includes(card.key)){keys.add(card.key);cards.push(card);}}for(let i=0;i<MAPS.length;i++)for(let specs of [0,1,2].flatMap(encounter=>new Battle(i,null,{encounter,campaignId:battle.campaignId}).waves))for(let spec of specs){const key=spec.type==='boss'?`boss:${MAPS[i].id}:${campaignMap(i,battle.campaignId).boss}`:enemyKey(spec,i);if(keys.has(key)||!journey.seen.includes(key))continue;keys.add(key);cards.push(...introductions([spec],i,[],campaignMap(i,battle.campaignId)));}
 $('journalList').innerHTML=cards.length?cards.map((card,i)=>`<details class="journal-entry"><summary>${card.name}${card.protection?' · '+BY_ID[card.protection].name+'’s protection':''}</summary><div><canvas id="journal-${i}" width="110" height="140" aria-label="${card.name}"></canvas><p>${card.hint}${card.protectionText?' '+card.protectionText:''}</p></div></details>`).join(''):'<p>New enemies will be recorded here after their first introduction.</p>';cards.forEach((card,i)=>paintEnemyPortrait($('journal-'+i),images[card.atlas]||images.enemies,card.family,card.cell??null));openDialog('journalDialog');}
$('journal').onclick=openJournal;
function newBattle(i,encounter=0,mode='campaign',campaignId=battle.campaignId,options={}){const difficulty=options.difficulty||battle.difficulty;const prior=battle;battle=new Battle(i,null,{encounter,difficulty,mode,campaignId:mode==='survival'?'river':campaignId,quickLength:options.quickLength??prior.quickLength,seed:options.seed??prior.seed});journey=campaignProgress(rootJourney,battle.campaignId);hasBattle=true;menuOpen=false;$('mainMenu').hidden=true;$('gameScreen').hidden=false;targeting=null;inspectedEnemy=null;lastFieldKey='';fieldUntil=0;$('fieldDialogue').hidden=true;paused=false;selectedPlot=null;endHandled=false;wonAge=0;pendingWave=null;$('result').hidden=true;$('victoryDetails').hidden=true;refreshPlots();updateSelection();updateUI();save();openStory();}
function askConfirm(title,text,label,action){$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmYes').textContent=label;confirmAction=action;openDialog('confirmDialog');}
$('restart').onclick=()=>askConfirm('Restart this battle?','Current shrines and offerings will reset. Restored temples and achievement lamps remain saved.','Restart',()=>newBattle(battle.mapIndex,battle.encounter,battle.mode));$('confirmCancel').onclick=()=>closeDialog('confirmDialog');$('confirmYes').onclick=()=>{closeDialog('confirmDialog');confirmAction?.();};$('victoryDetails').onclick=()=>{$('result').hidden=false;$('victoryDetails').hidden=true;};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&battle.status==='fighting'){paused=true;save();updateUI();}});window.addEventListener('pagehide',save);document.addEventListener('keydown',e=>{if(e.code==='Escape'&&targeting){cancelTarget();return;}if(targeting?.kind==='intervention'&&['ArrowLeft','ArrowRight'].includes(e.code)){e.preventDefault();const direction=e.code==='ArrowRight'?1:-1;targeting.pathIndex=Math.max(0,Math.min(battle.map.points.length-1,(targeting.pathIndex??0)+direction));const [x,y]=battle.map.points[targeting.pathIndex];targeting.point={x,y};updateUI();return;}if(e.code==='Space'&&!menuOpen&&!activeDialogs()&&!['BUTTON','SELECT','INPUT'].includes(document.activeElement.tagName)){e.preventDefault();if(battle.status==='fighting')$('pause').click();}});
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;if(targeting&&!targetAvailability(battle,targeting.plot,targeting.kind).ok){targeting=null;}const stopped=menuOpen||paused||activeDialogs()||!!targeting;if(!stopped)for(let i=0;i<speed;i++)battle.tick(dt);if(!stopped||battle.status!=='fighting')battle.animate(dt);if(battle.status==='won')wonAge+=dt;draw(battle,{targeting,inspectedEnemy,now:stopped?battle.time*1000:now,paused:stopped,selectedPlot,selectedDeity,journey,wonAge});uiClock+=dt;saveClock+=dt;if(uiClock>.2){updateUI();uiClock=0;}if(saveClock>3){save();saveClock=0;}requestAnimationFrame(frame);}
function nearestPathPoint(x,y){let best={x:0,y:0,distance:Infinity};const p=battle.map.points;for(let i=1;i<p.length;i++){const [ax,ay]=p[i-1],[bx,by]=p[i],dx=bx-ax,dy=by-ay,t=Math.max(0,Math.min(1,((x-ax)*dx+(y-ay)*dy)/(dx*dx+dy*dy))),px=ax+t*dx,py=ay+t*dy,distance=Math.hypot(x-px,y-py);if(distance<best.distance)best={x:px,y:py,distance};}return best;}
function updateActiveControls(){const local=chapterFor(battle),kali=battle.enemies.some(e=>e.boon==='raktabija'),remaining=Math.ceil(Math.max(0,(kali?battle.kaliReadyAt||0:battle.featureUntil)-battle.time));$('featureButton').textContent=(kali?'Call Kali · prevent echoes':local.feature)+(battle.mapIndex===0?' · reveal +15 charge':'')+(remaining?' · '+remaining+'s':'');$('featureButton').disabled=battle.status!=='fighting'||remaining>0||(battle.mapIndex===4&&battle.featureUses>=3);$('featureHint').textContent=kali?'Prevents new echoes for 10 seconds; recharges in 18 seconds. Existing echoes remain.':local.featureHint;$('escortButton').textContent=local.objective+' · optional';$('escortButton').disabled=battle.status!=='fighting'||battle.escort.state!=='waiting'||battle.wave<2||battle.wave>battle.totalWaves-2;$('escortStatus').textContent=battle.escort.state==='waiting'?'Dispatch between wave 2 and two waves before the end. +100 offerings for a completed crossing; no last-second bonus.':battle.escort.state==='travelling'?`${local.escort}: ${Math.max(0,battle.escort.health)} resolve remaining` :battle.escort.state==='safe'?'The bearers reached safety.':'The bearers retreated; the bonus is lost.';
 const readyDurga=battle.shrines.find(s=>s.deity==='durga'&&targetAvailability(battle,s.plot).ok);$('durgaReady').hidden=!readyDurga||battle.status!=='fighting';const shrine=battle.shrines.find(s=>s.plot===selectedPlot);if($('strikeButton')){const availability=targetAvailability(battle,shrine.plot);$('strikeButton').disabled=!availability.ok;$('strikeButton').textContent=availability.label;}
 if(targeting&&!targetAvailability(battle,targeting.plot,targeting.kind).ok)targeting=null;if(['won','lost'].includes(battle.status))targeting=null;$('targetControls').hidden=!targeting;$('targetHint').textContent=targeting?.kind==='strike'?'Paused — choose a visible foe, or cancel and resume.':'Time paused: tap the path (or use left/right arrow keys), check the marked area, then confirm.';$('enemyTarget').hidden=targeting?.kind!=='strike';$('confirmTarget').textContent=targeting?.kind==='strike'?'Strike selected foe':'Confirm intervention';$('confirmTarget').hidden=!targeting;$('confirmTarget').disabled=targeting?.kind==='intervention'&&!targeting.point;if(targeting?.kind==='strike'){const old=$('enemyTarget').value;$('enemyTarget').innerHTML=battle.enemies.filter(e=>battle.canAffect(e,'durga')&&battle.visible(e)).map(e=>`<option value="${e.id}">${e.name} · ${Math.ceil(e.hp)} health</option>`).join('');if([...$('enemyTarget').options].some(o=>o.value===old))$('enemyTarget').value=old;}
 const e=battle.enemies.find(e=>e.id===inspectedEnemy);$('enemyInspector').hidden=!e;if(e){const effects=[e.burnUntil>battle.time?'Burning':null,e.wetUntil>battle.time?'Wet':null,e.crackUntil>battle.time?'Armour cracked':null,!battle.visible(e)?'Hidden':null,e.stopped?'Armour open':null].filter(Boolean);$('enemyInspector').textContent=`${e.name} · ${Math.ceil(Math.max(0,e.hp))}/${Math.ceil(e.maxHp)} health${e.protection?' · Protected by '+BY_ID[e.protection].name:''}${effects.length?' · '+effects.join(', '):''}${e.boss?' · '+battle.map.boon:''}`;}
}
$('durgaReady').onclick=()=>{const s=battle.shrines.find(s=>s.deity==='durga'&&targetAvailability(battle,s.plot).ok);if(s){choosePlot(s.plot);beginTarget('strike',s.plot);}};$('featureButton').onclick=()=>{battle.useFeature();updateUI();save();};$('escortButton').onclick=()=>{battle.sendEscort();updateUI();save();};$('cancelTarget').onclick=cancelTarget;$('confirmTarget').onclick=()=>{if(targeting&&(targeting.kind==='strike'?battle.strike(targeting.plot,Number($('enemyTarget').value)):battle.intervention(targeting.plot,targeting.point))){targeting=null;updateUI();save();}};$('difficultySelect').onchange=e=>{battle.setDifficulty(e.target.value);updateUI();save();};$('blessingSelect').onchange=e=>{battle.setBlessing(e.target.value);updateUI();save();};$('survivalButton').onclick=()=>{closeDialog('campaignDialog');if(battle.wave&&!['won','lost'].includes(battle.status))askConfirm('Leave this battle?','Saved victories remain. Begin the unending vigil?','Begin vigil',()=>newBattle(4,2,'survival'));else newBattle(4,2,'survival');};for(const b of document.querySelectorAll('[data-gift]'))b.onclick=()=>{if(battle.survivalGift(b.dataset.gift)){closeDialog('survivalDialog');updateUI();save();}};$('survivalDialog').addEventListener('cancel',e=>e.preventDefault());
$('continueBattle').onclick=continueJourney;$('replayBattle').onclick=()=>newBattle(battle.mapIndex,battle.encounter,battle.mode);$('showResults').onclick=()=>{$('result').hidden=false;};
function updateFieldDialogue(){const line=fieldLine(battle);if(line&&battle.status==='fighting'){const key=line.speaker+':'+line.text;if(key!==lastFieldKey){lastFieldKey=key;fieldUntil=battle.time+7;$('fieldSpeaker').textContent=CAST[line.speaker].name;$('fieldWords').textContent=line.text;$('fieldDialogue').hidden=false;}}if(battle.time>fieldUntil||battle.status!=='fighting')$('fieldDialogue').hidden=true;}

function renderMainMenu(){
 $('resumeGame').hidden=!hasBattle;$('resumeGame').disabled=!ready;
 $('resumeGame').textContent=hasBattle?'Continue '+(battle.mode==='quick'?'Quick Battle':campaignInfo(battle.campaignId).name)+' · wave '+battle.wave:'Continue';
 $('campaignCards').innerHTML=CAMPAIGNS.map(c=>{const progress=campaignProgress(rootJourney,c.id);return `<article class="campaign-card ${c.id}"><img src="assets/${c.art}.webp" alt=""><div class="campaign-card-body"><span class="panel-eyebrow">${c.tag}</span><h2>${c.name}</h2><p>${c.description}</p><small>15 encounters · ${Object.keys(progress.temples).length}/5 temples restored</small><button class="primary" data-expedition="${c.id}" ${ready?'':'disabled'}>Choose a stage →</button></div></article>`;}).join('');
 for(const button of document.querySelectorAll('[data-expedition]'))button.onclick=()=>openCampaign(button.dataset.expedition);
 $('quickStart').disabled=!ready;
}
function showMenu(){menuOpen=true;paused=battle.status==='fighting';targeting=null;save();$('gameScreen').hidden=true;$('mainMenu').hidden=false;renderMainMenu();window.scrollTo({top:0});}
$('mainMenuButton').onclick=showMenu;
$('resumeGame').onclick=()=>{menuOpen=false;$('mainMenu').hidden=true;$('gameScreen').hidden=false;updateUI();};
$('menuGuide').onclick=()=>openDialog('guideDialog');
$('quickMap').innerHTML=MAPS.map((m,i)=>`<option value="${i}">${m.name}</option>`).join('');
$('quickStart').onclick=()=>{const start=()=>newBattle(Number($('quickMap').value),2,'quick','river',{difficulty:$('quickDifficulty').value,quickLength:Number($('quickLength').value),seed:crypto.getRandomValues(new Uint32Array(1))[0]});if(hasBattle&&!['won','lost'].includes(battle.status)&&(battle.wave||battle.shrines.length))askConfirm('Start a quick battle?','This replaces the unfinished battle. Completed campaign stages and lamps stay saved.','Start battle',start);else start();};
initRoster();refreshPlots();updateSelection();updateUI();renderMainMenu();

async function loadArt(){const names=['courtyard','lotus','town','mountain','spring','shrines','honoured','exalted','spells','restoration','enemies','guardian','myth-enemies','myth-bosses'];await Promise.all(names.map(name=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{images[name]=img;resolve();};img.onerror=()=>reject(new Error(name));img.src=`assets/${name}.webp`;})));ready=true;$('menuStatus').hidden=true;$('loading').hidden=true;updateUI();last=performance.now();requestAnimationFrame(frame);renderMainMenu();}
loadArt().catch(()=>{$('menuStatus').textContent='Artwork could not load. Refresh this page to try again.';$('loading').innerHTML='Some artwork could not load. <button id="retryLoad">Try again</button>';$('retryLoad').onclick=()=>location.reload();});
